// Express 示例：带凭证的跨域 API 正确配置
const ALLOW_LIST = new Set([
  'https://app.example.com',
  'https://admin.example.com'
]);

app.use((req, res, next) => {
  const origin = req.headers.origin;
  // 关键 1：不能写成 '*'，必须回显具体 Origin，否则带凭证请求被浏览器拦截
  // 同时只回显在白名单里的 Origin，避免 Reflected CORS 漏洞
  if (origin && ALLOW_LIST.has(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin);
    // 关键 2：Vary: Origin 防止 CDN/反向代理把 A 站响应缓存后错发给 B 站
    res.setHeader('Vary', 'Origin');
    res.setHeader('Access-Control-Allow-Credentials', 'true');
  }
  if (req.method === 'OPTIONS') {
    // 关键 3：带凭证时 Allow-Headers 也不能用 '*'，要列真实值
    res.setHeader('Access-Control-Allow-Methods', 'GET,POST,PUT,DELETE');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization, X-Request-Id');
    res.setHeader('Access-Control-Max-Age', '600'); // 预检结果缓存 10 分钟
    return res.status(204).end();
  }
  next();
});

// 登录接口设置跨站 Cookie（前端在 app.com，API 在 api.example.com）
app.post('/login', (req, res) => {
  res.cookie('SID', sessionId, {
    httpOnly: true,        // JS 读不到，缓解 XSS 偷 Session
    secure: true,          // 只在 HTTPS 下发送，SameSite=None 必须搭配
    sameSite: 'none',      // 允许跨站携带（Chrome 80+ 默认是 Lax）
    domain: '.example.com',// 只对自家子域生效，不会泄漏给 evil.com
    maxAge: 7 * 24 * 3600 * 1000
  });
  res.json({ ok: true });
});

// ❌ 漏洞：不校验 Origin，直接回显 —— 等效于 * 且带凭证
app.use((req, res, next) => {
  const origin = req.headers.origin;
  if (origin) {
    // 危险！evil.com 发请求过来也会回显 evil.com
    res.setHeader('Access-Control-Allow-Origin', origin);
    res.setHeader('Access-Control-Allow-Credentials', 'true');
  }
  next();
});

// ✅ 修复：白名单校验后回显
const ALLOW_LIST = new Set(['https://app.example.com']);

app.use((req, res, next) => {
  const origin = req.headers.origin;
  if (origin && ALLOW_LIST.has(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin);
    res.setHeader('Vary', 'Origin');
    res.setHeader('Access-Control-Allow-Credentials', 'true');
  }
  next();
});
